  border-radius: 5px;
  min-width: 26px;
  padding: 2px 7px;
  text-align: center;
}
.clear-button {
  color: var(--muted);
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  flex: none;
  border: 0;
  border-radius: 5px;
  background: transparent;
}
.clear-button:hover {
  color: var(--text);
  background: #2a2130;
}
.search-help {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  min-height: 20px;
  margin: 12px 2px 0;
}
.results-list,
.loading-rows {
  border-top: 1px solid var(--line);
}
.loading-rows {
  width: 100%;
}
.entity-row {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 21px 0;
  border-bottom: 1px solid var(--line);
}
.entity-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
