  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, black);
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent) 20%, black);
  color: color-mix(in srgb, var(--accent), white 40%);
  font-size: 12px;
  line-height: 1.5;
}
.entity-kind svg {
  flex: none;
  color: var(--accent);
}
.entity-kind-label {
  min-width: 0;
  overflow-wrap: anywhere;
}
