  line-height: 1.5;
  overflow-wrap: anywhere;
  box-shadow: 0 4px 16px #0008;
}
.message-state {
  display: flex;
  align-items: center;
  flex-direction: column;
  text-align: center;
  padding: 48px 12px 44px;
}
.state-icon {
  display: grid;
  place-items: center;
  color: var(--muted);
